import time


def retry_with_backoff(func, max_retries=3, initial_delay=0.1, backoff_factor=2, *, retry_on=(Exception,), max_delay=None, sleep=None):
    # --- validation (before calling func) ---
    if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
        raise ValueError("max_retries must be a non-bool integer >= 0")
    if isinstance(initial_delay, bool) or not isinstance(initial_delay, (int, float)) or not (initial_delay == initial_delay) or initial_delay in (float("inf"), float("-inf")) or initial_delay < 0:
        raise ValueError("initial_delay must be a finite non-bool number >= 0")
    if isinstance(backoff_factor, bool) or not isinstance(backoff_factor, (int, float)) or not (backoff_factor == backoff_factor) or backoff_factor in (float("inf"), float("-inf")) or backoff_factor < 1:
        raise ValueError("backoff_factor must be a finite non-bool number >= 1")
    if max_delay is not None:
        if isinstance(max_delay, bool) or not isinstance(max_delay, (int, float)) or not (max_delay == max_delay) or max_delay in (float("inf"), float("-inf")) or max_delay < 0:
            raise ValueError("max_delay must be None or a finite non-bool number >= 0")
    if not isinstance(retry_on, tuple) or len(retry_on) == 0 or not all(isinstance(t, type) and issubclass(t, Exception) for t in retry_on):
        raise ValueError("retry_on must be a nonempty tuple of Exception subclass types")

    _sleep = time.sleep if sleep is None else sleep

    attempt = 0  # zero-based count of retryable failures so far
    while True:
        try:
            return func()
        except Exception as exc:
            # Never retry BaseException subclasses outside Exception
            if not isinstance(exc, Exception):
                raise
            # Retry only exceptions matching retry_on
            if not any(isinstance(exc, t) for t in retry_on):
                raise
            # Exhausted: re-raise the exact last exception object
            if attempt >= max_retries:
                raise
            # Compute delay for retryable failure number `attempt`
            delay = initial_delay * (backoff_factor ** attempt)
            if max_delay is not None:
                delay = min(delay, max_delay)
            _sleep(delay)
            attempt += 1
